import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse(`{"title":"PEFT (Bridge)","description":"Engineering-decision bridge for parameter-efficient fine-tuning (LoRA/QLoRA): cutting the cost of 'weights must move' by an order of magnitude, and how the adapter architecture changes deployment shape.","frontmatter":{"title":"PEFT (Bridge)","description":"Engineering-decision bridge for parameter-efficient fine-tuning (LoRA/QLoRA): cutting the cost of 'weights must move' by an order of magnitude, and how the adapter architecture changes deployment shape.","domain":"tech","tags":["tech","training","bridge","peft","lora"],"navOrder":143,"topicId":"model-lifecycle-peft","layer":"1","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"tech/01-model-lifecycle/post-training/peft.md","filePath":"tech/01-model-lifecycle/post-training/peft.md","lastUpdated":1791122193000}`),r={name:"tech/01-model-lifecycle/post-training/peft.md"};function i(s,e,l,d,c,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<blockquote><p><strong>Group</strong>: Model Lifecycle (bridge) | <strong>Previous group exit</strong>: inference fundamentals and interface contracts | <strong>This page exit</strong>: know when to change weights instead of prompts or retrieval</p></blockquote><h1 id="peft-bridge" tabindex="-1">PEFT (Bridge) <a class="header-anchor" href="#peft-bridge" aria-label="Permalink to &quot;PEFT (Bridge)&quot;">​</a></h1><blockquote><p><strong>Bridge page</strong>: this page answers only the engineering-decision question. The low-rank math of LoRA and the quantization combination of QLoRA are derived in <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> (LoRA chapter).</p></blockquote><h2 id="what-problem-it-solves" tabindex="-1">What problem it solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What problem it solves&quot;">​</a></h2><p><strong>Parameter-Efficient Fine-Tuning (PEFT)</strong> is a family of techniques: freeze the full weights of the pretrained model and train only a small set of added parameters — the most popular being <strong>LoRA (Low-Rank Adaptation)</strong>, which learns &quot;the modification to the weights&quot; as two low-rank matrices. The effect is to shift SFT&#39;s cost structure down by an order of magnitude:</p><ul><li><strong>Lower hardware bar</strong>: consumer/single-GPU setups become viable (versus cluster-scale full fine-tuning).</li><li><strong>Tiny artifacts</strong>: training produces MB-scale &quot;adapter&quot; files instead of GB-scale full model copies.</li><li><strong>One base, many adapters</strong>: the serving side can share one base model and hot-swap adapters per request — the standard shape for multi-tenant customization.</li></ul><p>A memorable (non-strict) analogy: full fine-tuning rewrites the whole book; LoRA writes edits on sticky notes attached to the relevant pages, and reading applies &quot;original + sticky notes&quot; together.</p><h2 id="when-you-arrive-at-this-page" tabindex="-1">When you arrive at this page <a class="header-anchor" href="#when-you-arrive-at-this-page" aria-label="Permalink to &quot;When you arrive at this page&quot;">​</a></h2><p>PEFT is not an independent decision — it is the <strong>cost-reduced execution mode</strong> of the <a href="./sft.html">SFT (bridge)</a> decision. Trigger conditions are the same as SFT (prompt and RAG exhausted, labeled data available, budget available), plus two typical scenarios:</p><ol><li><strong>Many variants needed</strong>: one base model must yield multiple custom versions (per customer, per task); full fine-tuning per variant is unaffordable.</li><li><strong>Local/privacy deployment</strong>: run a fine-tuned open-source model (Llama, Mistral, ...) on your own hardware so data never leaves the domain.</li></ol><h2 id="decision-impact-table" tabindex="-1">Decision impact table <a class="header-anchor" href="#decision-impact-table" aria-label="Permalink to &quot;Decision impact table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Full SFT</th><th>PEFT (LoRA/QLoRA)</th></tr></thead><tbody><tr><td><strong>Data requirement</strong></td><td>Same volume of labeled pairs (data cost unchanged; specific thresholds unverified)</td><td>Same — PEFT saves compute, not data</td></tr><tr><td><strong>Cost structure</strong></td><td>Every run yields a full model copy; storage and distribution are expensive</td><td>Training compute and storage drop significantly (the order-of-magnitude comparison is community consensus; exact multiples unverified)</td></tr><tr><td><strong>Inference latency</strong></td><td>Same class as the original model</td><td>Near-parity after adapter merging; note some hosted APIs do not accept external adapters</td></tr><tr><td><strong>Maintenance burden</strong></td><td>One full model per custom version; a large version matrix</td><td>Base version + adapter matrix; every adapter needs regression when the base is upgraded</td></tr><tr><td><strong>Effect ceiling</strong></td><td>Highest theoretical ceiling</td><td>Enough for most customization tasks; extreme domain shifts may still need full fine-tuning</td></tr></tbody></table><h2 id="connection-to-local-inference" tabindex="-1">Connection to local inference <a class="header-anchor" href="#connection-to-local-inference" aria-label="Permalink to &quot;Connection to local inference&quot;">​</a></h2><p>If you run models locally with Ollama, LM Studio and the like, you already consume this chain — &quot;quantized models&quot; and &quot;LoRA adapters&quot; are two key prerequisites for running large models locally. Browser/edge inference is expanded in the mainline <a href="./../../02-inference-interface/browser-edge.html">Browser and edge inference</a>; quantization math belongs to Learn LLM.</p><h2 id="lora-s-engineering-choices" tabindex="-1">LoRA&#39;s engineering choices <a class="header-anchor" href="#lora-s-engineering-choices" aria-label="Permalink to &quot;LoRA&#39;s engineering choices&quot;">​</a></h2><p>After deciding &quot;use LoRA&quot;, three engineering choices remain; their derivations live in Learn LLM — only the decision meaning is listed here:</p><ul><li><strong>Rank</strong>: controls the expressive power of the &quot;sticky notes&quot;. Higher rank = more capability at more cost; the common practice is starting small and letting eval sets decide whether to go up (recommended values unverified; experiment).</li><li><strong>Target layers</strong>: attention-only vs also the feed-forward layers — a capability/cost trade-off.</li><li><strong>QLoRA</strong>: quantize the base first, then LoRA — memory demand drops further at the cost of an extra layer of quantization error in training and inference. The default upgrade path when memory runs out, not a quality-improving choice.</li></ul><p>The common thread: <strong>all three should be eval-set-driven</strong>, not copied from someone else&#39;s config — &quot;their rank&quot; was tuned on their data and task.</p><h2 id="deep-derivations-and-implementation" tabindex="-1">Deep derivations and implementation <a class="header-anchor" href="#deep-derivations-and-implementation" aria-label="Permalink to &quot;Deep derivations and implementation&quot;">​</a></h2><ul><li>LoRA low-rank math, rank selection, QLoRA quantization combinations → the LoRA chapter of <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>.</li><li>Original paper: <a href="https://arxiv.org/abs/2106.09685" target="_blank" rel="noreferrer">LoRA: Low-Rank Adaptation of Large Language Models</a>; implementation library: <a href="https://github.com/huggingface/peft" target="_blank" rel="noreferrer">HuggingFace PEFT</a>.</li></ul>',20)])])}const b=t(r,[["render",i]]);export{f as __pageData,b as default};
